Here is the commit message:
PCI/P2PDMA: Release per-CPU pgmap ref when vm_insert_page()
 fails

When vm_insert_page() fails in p2pmem_alloc_mmap(), p2pmem_alloc_mmap()
doesn't invoke percpu_ref_put() to free the per-CPU ref of pgmap acquired
after gen_pool_alloc_owner(), and memunmap_pages() will hang forever when
trying to remove the PCI device.

Fix it by adding the missed percpu_ref_put().

Fixes: 7e9c7ef83d78 ("PCI/P2PDMA: Allow userspace VMA allocations through sysfs")
Signed-off-by: Hou Tao <houtao1@huawei.com>
Signed-off-by: Bjorn Helgaas <bhelgaas@google.com>
Reviewed-by: Logan Gunthorpe <logang@deltatee.com>
Reviewed-by: Alistair Popple <apopple@nvidia.com>
Link: https://patch.msgid.link/20251220040446.274991-2-houtao@huaweicloud.com

Here is the root cause:
In `p2pmem_alloc_mmap()`, when `vm_insert_page()` fails, the code calls `gen_pool_free()` to free the allocated memory but does not call `percpu_ref_put()` to release the per-CPU reference count acquired earlier. This leaves the reference count elevated, causing `memunmap_pages()` to hang indefinitely when the PCI device is removed.

Here is the patch:

 static int p2pmem_alloc_mmap(struct file *filp, struct kobject *kobj,
 		const struct bin_attribute *attr, struct vm_area_struct *vma)
 {
 	struct pci_dev *pdev = to_pci_dev(kobj_to_dev(kobj));
 	size_t len = vma->vm_end - vma->vm_start;
 	struct pci_p2pdma *p2pdma;
 	struct percpu_ref *ref;
 	unsigned long vaddr;
 	void *kaddr;
 	int ret;

 	/* prevent private mappings from being established */
 	if ((vma->vm_flags & VM_MAYSHARE) != VM_MAYSHARE) {
 		pci_info_ratelimited(pdev,
 				     "%s: fail, attempted private mapping\n",
 				     current->comm);
 		return -EINVAL;
 	}

 	if (vma->vm_pgoff) {
 		pci_info_ratelimited(pdev,
 				     "%s: fail, attempted mapping with non-zero offset\n",
 				     current->comm);
 		return -EINVAL;
 	}

 	rcu_read_lock();
 	p2pdma = rcu_dereference(pdev->p2pdma);
 	if (!p2pdma) {
 		ret = -ENODEV;
 		goto out;
 	}

 	kaddr = (void *)gen_pool_alloc_owner(p2pdma->pool, len, (void **)&ref);
 	if (!kaddr) {
 		ret = -ENOMEM;
 		goto out;
 	}

 	/*
 	 * vm_insert_page() can sleep, so a reference is taken to mapping
 	 * such that rcu_read_unlock() can be done before inserting the
 	 * pages
 	 */
 	if (unlikely(!percpu_ref_tryget_live_rcu(ref))) {
 		ret = -ENODEV;
 		goto out_free_mem;
 	}
 	rcu_read_unlock();

 	for (vaddr = vma->vm_start; vaddr < vma->vm_end; vaddr += PAGE_SIZE) {
 		struct page *page = virt_to_page(kaddr);

 		/*
 		 * Initialise the refcount for the freshly allocated page. As
 		 * we have just allocated the page no one else should be
 		 * using it.
 		 */
 		VM_WARN_ON_ONCE_PAGE(!page_ref_count(page), page);
 		set_page_count(page, 1);
 		ret = vm_insert_page(vma, vaddr, page);
 		if (ret) {
 			gen_pool_free(p2pdma->pool, (uintptr_t)kaddr, len);
+			percpu_ref_put(ref);
 			return ret;
 		}
 		percpu_ref_get(ref);
 		put_page(page);
 		kaddr += PAGE_SIZE;
 		len -= PAGE_SIZE;
 	}

 	percpu_ref_put(ref);

 	return 0;
 out_free_mem:
 	gen_pool_free(p2pdma->pool, (uintptr_t)kaddr, len);
 out:
 	rcu_read_unlock();
 	return ret;
 }



